import sys
from typing import List
import json

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        # offline_until[u] stores the timestamp when user u comes back online.
        # Initially 0, meaning all users are online from the start.
        # If offline_until[u] <= current_timestamp, user u is online.
        offline_until = [0] * numberOfUsers

        # Sort events by timestamp.
        # If timestamps are equal, OFFLINE events (type 0) come before MESSAGE events (type 1).
        # This ensures status changes are processed before message handling at the same timestamp.
        sorted_events = sorted(events, key=lambda x: (int(x[1]), 0 if x[0] == "OFFLINE" else 1))

        for event in sorted_events:
            event_type = event[0]
            timestamp = int(event[1])

            if event_type == "OFFLINE":
                user_id = int(event[2])
                # User goes offline for 60 time units.
                # Returns online at timestamp + 60.
                offline_until[user_id] = timestamp + 60
            elif event_type == "MESSAGE":
                mentions_str = event[2]
                tokens = mentions_str.split()

                for token in tokens:
                    if token == "ALL":
                        for u in range(numberOfUsers):
                            mentions[u] += 1
                    elif token == "HERE":
                        for u in range(numberOfUsers):
                            # User is online if offline_until[u] <= timestamp
                            if offline_until[u] <= timestamp:
                                mentions[u] += 1
                    elif token.startswith("id"):
                        user_id = int(token[2:])
                        mentions[user_id] += 1

        return mentions

if __name__ == "__main__":
