class Solution:
    def maxDifference(self, s: str) -> int:
        # Count the frequency of each character in the string
        counts = Counter(s)

        max_odd_freq = -1
        min_even_freq = float('inf')

        # Iterate through the frequencies to find the maximum odd frequency
        # and the minimum even frequency
        for count in counts.values():
            if count % 2 == 1:
                if count > max_odd_freq:
                    max_odd_freq = count
            else:
                if count < min_even_freq:
                    min_even_freq = count

        # Return the maximum difference
        # Constraints guarantee at least one odd and one even frequency exist
        return max_odd_freq - min_even_freq

