    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total_sum = 0
        n = len(nums)
        for i in range(n):
            is_good = True

            # Check if strictly greater than left neighbor (if exists)
            # OR strictly greater than right neighbor (if exists)
            # If it fails either check, it's not good.
            if (i - k >= 0 and nums[i] <= nums[i - k]) or (i + k < n and nums[i] <= nums[i + k]):
                is_good = False

