from typing import List

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        # Helper function to calculate GCD of a list
        def calculate_gcd(arr):
            if not arr:
                return 0
            result = arr[0]
            for num in arr[1:]:
                result = math.gcd(result, num)
            return result

        # Helper function to calculate LCM of a list
        def calculate_lcm(arr):
            if not arr:
                return 0
            result = arr[0]
            for num in arr[1:]:
                # lcm(a, b) = (a * b) // gcd(a, b)
                result = (result * num) // math.gcd(result, num)
            return result

        # Helper function to calculate factor score
        def calculate_score(arr):
            if not arr:
                return 0
            return calculate_gcd(arr) * calculate_lcm(arr)

        n = len(nums)
        max_score = 0

        # Option 1: Do not remove any element
        max_score = max(max_score, calculate_score(nums))

        # Option 2: Remove exactly one element
        for i in range(n):
            # Create a new list excluding the element at index i
            # Slicing creates a copy, which is O(N)
            temp_nums = nums[:i] + nums[i+1:]
            score = calculate_score(temp_nums)
            if score > max_score:
                max_score = score

        return max_score

if __name__ == "__main__":
    # Read input from stdin
