class Solution:
    def answerString(self, word: str, numFriends: int) -> str:
        n = len(word)
        s = numFriends - 1
        k = n - s

        candidates = []

        for i in range(n):
            if i == 0:
                if s == 0:
                    l = n
                else:
                    l = k
            else:
                if s == 0:
                    l = min(k, n - i - 1)
                else:
                    if i >= s:
                        l = n - i
                    else:
                        l = k

            if l > 0:
                candidates.append(word[i : i + l])

        return max(candidates)
